	insert into cdn.slownikistruktura (SLS_OId, SLS_Lp, SLS_Nazwa, SLS_Predefiniowany, SLS_WartoscL1) values(@KsiegowoscID,182,'Grupy rejestrów k/b',182,0);
end

set nocount off;

set nocount on;

