set nocount off;

set nocount on;

declare @InneID int;
select @InneID=SLS_Id from cdn.SlownikiStruktura where SLS_Nazwa = 'Inne' and SLS_OId = 0
if not exists(select * from cdn.SlownikiStruktura where SLS_Nazwa = 'Przyczyny odrzucenia' and SLS_OId = @InneID)
begin
	insert into cdn.slownikistruktura (SLS_OId, SLS_Lp, SLS_Nazwa, SLS_Predefiniowany, SLS_WartoscL1) values(@InneID,185,'Przyczyny odrzucenia',185,0);
